/* @lc app=leetcode id=3971 lang=kotlin */ class Solution { fun cnt(v: IntArray, d: IntArray, t: Long): Long = v.indices.sumOf { i -> if (v[i] >= t) (v[i] - t) / d[i] + 1 else 0L } fun maxTotalValue(value: IntArray, decay: IntArray, m: Int): Int = generateSequence(1L to 1_000_000_001L) { (lo, hi) -> ((lo + hi) / 2).let { mid -> if (cnt(value, decay, mid) <= m) lo to mid else mid + 1 to hi } }.first { it.first >= it.second }.first.let { T -> (value.indices.sumOf { i -> if (value[i] >= T) ((value[i] - T) / decay[i] + 1).let { c -> (c % 1_000_000_007L * (value[i] % 1_000_000_007L) % 1_000_000_007L - decay[i].toLong() * (c - 1) % 1_000_000_007L * (c % 1_000_000_007L) % 1_000_000_007L * 500000004L % 1_000_000_007L + 1_000_000_007L) % 1_000_000_007L } else 0L } + (if (T > 1) (m - cnt(value, decay, T)) % 1_000_000_007L * ((T - 1) % 1_000_000_007L) else 0L)).let { Math.floorMod(it, 1_000_000_007L).toInt() } } }